#!/usr/bin/env bash
# Renders orders-api-slo.rules.yaml into a PrometheusRule CR for Argo CD to sync.
# The plain rules file stays the source of truth so promtool can test it directly:
#   promtool test rules lab/slo/orders-api-slo.test.yaml
#
#   ./render.sh          write k8s/orders-api-slo.yaml (commit the result)
#   ./render.sh --check  exit 1 if the committed file is out of date (for CI)
set -euo pipefail
cd "$(dirname "$0")"
out=k8s/orders-api-slo.yaml

render() {
  cat <<'HDR'
# GENERATED by lab/slo/render.sh from orders-api-slo.rules.yaml. Do not edit.
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: orders-api-slo
  namespace: monitoring
  labels:
    app.kubernetes.io/name: orders-api-slo
spec:
HDR
  grep -v '^#' orders-api-slo.rules.yaml | sed 's/^/  /'
}

if [[ "${1:-}" == "--check" ]]; then
  diff -u "$out" <(render) && echo "$out is up to date"
else
  render > "$out" && echo "wrote $out"
fi
